inbound.set-body:
@{
            var body = context.Request.Body.As();

            // Only include properties that were provided in the request so unspecified fields aren't overwritten
            var movie = new JObject();
            if (body["title"] != null)
            {
                movie["Title"] = body["title"];
            }
            if (body["description"] != null)
            {
                movie["Description"] = body["description"];
            }
            if (body["year"] != null)
            {
                movie["Year"] = body["year"];
            }
            if (body["rating"] != null)
            {
                movie["Rating"] = body["rating"];
            }

            return movie.ToString(Newtonsoft.Json.Formatting.None);
        }
